function themedPool(r,kind){
 let out=[];for(const t of (r.settings.themes||[])){for(const x of (THEME_BANKS[t]?.[kind]||[]))out.push({theme:t,value:x})}
 if(!out.length)for(const [t,b] of Object.entries(THEME_BANKS))for(const x of (b[kind]||[]))out.push({theme:t,value:x});
 return out;
}
function themedPick(r,kind){
 const available=Object.keys(THEME_BANKS).filter(t=>(THEME_BANKS[t]?.[kind]||[]).length);
 const t=chooseTheme(r,'allGames',available);
 const x=unusedPick(r,'theme:'+kind+':'+t,THEME_BANKS[t][kind]);
 return {theme:t,value:x};
}

function unusedPick(r,key,arr){
 r.used=r.used||{};r.used[key]=r.used[key]||[];
 let available=arr.map((x,i)=>i).filter(i=>!r.used[key].includes(i));
 if(!available.length){r.used[key]=[];available=arr.map((x,i)=>i)}
 const i=available[Math.floor(Math.random()*available.length)];r.used[key].push(i);return arr[i];
}

