function makeDuelPairs(r){
 const ids=Object.keys(r.players);
 r.duelRotation=(r.duelRotation||0)+1;
 // deterministic rotation: changes opponents every round without random duplicate pairing
 const base=[...ids];
 if(base.length>2){
   const shift=r.duelRotation%base.length;
   base.push(...base.splice(0,shift));
 }
 const pairs=[];
 for(let i=0;i+1<base.length;i+=2)pairs.push([base[i],base[i+1]]);
 return {pairs,bye:base.length%2?base[base.length-1]:null};
}
function pickDuelPrompt(r,keySuffix){
 let pool=[];
 for(const t of r.settings.themes||[])for(const x of (DUEL_THEME_BANK[t]||[]))pool.push({t,x});
 if(!pool.length)for(const [t,a] of Object.entries(DUEL_THEME_BANK))for(const x of a)pool.push({t,x});
 const av=[...new Set(pool.map(o=>o.t))],tt=chooseTheme(r,'duel:'+keySuffix,av),tp=pool.filter(o=>o.t===tt);
 return unusedPick(r,'duelPair:'+keySuffix+':'+tt,tp);
}
function pickWhoNoRepeat(r){
 let available=Object.keys(WHO_BANK).filter(t=>(r.settings.themes||[]).includes(t)&&(WHO_BANK[t]||[]).some(w=>/^https?:\/\//.test(w[2]||'')));
 if(!available.length)available=Object.keys(WHO_BANK).filter(t=>(WHO_BANK[t]||[]).some(w=>/^https?:\/\//.test(w[2]||'')));
 r.usedWhoNames=r.usedWhoNames||[];
 let candidates=[];
 for(const t of available)for(const w of (WHO_BANK[t]||[])){
   if(/^https?:\/\//.test(w[2]||'')&&!r.usedWhoNames.includes(String(w[0]).toLowerCase()))candidates.push({t,w});
 }
 if(!candidates.length){r.usedWhoNames=[];for(const t of available)for(const w of (WHO_BANK[t]||[]))if(/^https?:\/\//.test(w[2]||''))candidates.push({t,w})}
 const z=candidates[Math.floor(Math.random()*candidates.length)];
 r.usedWhoNames.push(String(z.w[0]).toLowerCase());
 return z;
}
